for name, change in changes.items():
    path = Path(name)
    source = path.read_text()
    assert hashlib.sha256(source.encode()).hexdigest() == change['base'], 'Source changed: ' + name
    lines = source.splitlines(keepends=True)
    for start, end, text in reversed(change['edits']):
        lines[start:end] = [text]
    result = ''.join(lines)
    assert hashlib.sha256(result.encode()).hexdigest() == change['result'], 'Result differs: ' + name
    path.write_text(result)
    print('Verified', name)
